        long block = (n - 1) / 4;
        // Rows in this block:
        // Att 1: 4*block + 1, 4*block + 2
        // Att 2: 4*block + 3, 4*block + 4

        // Determine if n is in the first half or second half of the block.
        // If n % 4 == 1 or n % 4 == 2, it's the first pair of rows in this block.
        // If n % 4 == 3 or n % 4 == 0, it's the second pair of rows in this block.

        // Let's calculate the time taken to complete all previous blocks.
        // Each block consists of:
        // 1. Serve first pair (6s)
        // 2. Move 1 row (1s)
        // 3. Serve second pair (6s)
        // 4. Move 3 rows (3s)
        // Total time per block = 6 + 1 + 6 + 3 = 16 seconds.

