            // Step 1: Serve Row 1 (Att 1) and Row 3 (Att 2).
            //   This corresponds to posInBlock 0 (Row 1) and posInBlock 2 (Row 3).
            //   They are served simultaneously.
            // Step 2: Move 1 row.
            // Step 3: Serve Row 2 (Att 1) and Row 4 (Att 2).
            //   This corresponds to posInBlock 1 (Row 2) and posInBlock 3 (Row 4).
            //   They are served simultaneously.
            // Step 4: Move 3 rows.

            // So:
            // If posInBlock is 0 or 2:
            //   The row is served in the first phase of the block.
            //   Time added before serving: 0.
            // If posInBlock is 1 or 3:
            //   The row is served in the second phase of the block.
            //   Time added before serving: 6 (serve first phase) + 1 (move) = 7.

            // Let's correct the logic above.
            // posInBlock 0: Row 1. Phase 1.
            // posInBlock 1: Row 2. Phase 2.
            // posInBlock 2: Row 3. Phase 1.
            // posInBlock 3: Row 4. Phase 2.

            // So:
            if (posInBlock == 0 || posInBlock == 2) {
                // Phase 1
                // currentTime is already timeBeforeBlock.
                // No extra time added before serving.
            } else {
                // Phase 2
                currentTime += 7;
            }
        }

        // Now, add the time within the row.
        // The attendant serves in order: f, e, d, a, b, c.
        // Seat 'f' is 1st (1 sec wait? No, "1 second to serve one passenger". 
        // "how many seconds will pass before he gets his lunch".
        // If he is the first, 1 second passes.
        // So, index 0 -> 1 sec, index 1 -> 2 sec, etc.

        int seatIndex;
        switch (seat) {
            case 'f': seatIndex = 0; break;
            case 'e': seatIndex = 1; break;
            case 'd': seatIndex = 2; break;
            case 'a': seatIndex = 3; break;
            case 'b': seatIndex = 4; break;
            case 'c': seatIndex = 5; break;
            default: seatIndex = 0; break; // Should not happen
        }

        currentTime += seatIndex + 1;

        System.out.println(currentTime);
    }
