        }

        // Time to complete all phases before this phase:
        // Phases 0 to phase-1
        // Each pair of phases (0,1), (2,3), ... takes 7 + 9 = 16 seconds
        // Number of complete pairs before phase: phase / 2
        // If phase is even, we have phase/2 complete pairs
        // If phase is odd, we have (phase-1)/2 complete pairs plus one more phase

        long timeBeforePhase;
