        if (rowInCycle == 0 || rowInCycle == 1) {
            isAttendant1 = true;
        } else {
            isAttendant1 = false;
        }

        // Calculate the time when the attendant starts serving this row
        // The attendants move in a pattern:
        // Start: Att1 at row 1, Att2 at row 3
        // After serving rows 1 and 3 (6 seconds each, but they work in parallel), they move 1 row forward (1 second)
        // Then serve rows 2 and 4 (6 seconds), then move 3 rows forward (3 seconds)
        // Then serve rows 5 and 7 (6 seconds), then move 1 row forward (1 second)
        // Then serve rows 6 and 8 (6 seconds), then move 3 rows forward (3 seconds)
        // ...

        // Let's think about the timeline:
        // Time 0: Att1 at row 1, Att2 at row 3
        // Time 1-6: Serving row 1 (Att1) and row 3 (Att2). At time 6, both finish.
        // Time 7: Move 1 row forward. Att1 at row 2, Att2 at row 4.
        // Time 8-13: Serving row 2 and row 4. At time 13, both finish.
        // Time 14-16: Move 3 rows forward. Att1 at row 5, Att2 at row 7.
        // Time 17-22: Serving row 5 and row 7. At time 22, both finish.
        // Time 23: Move 1 row forward. Att1 at row 6, Att2 at row 8.
        // Time 24-29: Serving row 6 and row 8. At time 29, both finish.
        // Time 30-32: Move 3 rows forward. Att1 at row 9, Att2 at row 11.

        // So the pattern of moves is: 1, 3, 1, 3, ...
        // Each "cycle" of two rows for each attendant takes: 6 (serve) + move time
        // But the moves alternate between 1 and 3.

        // Let's define a "super-cycle" as serving 2 rows for each attendant (4 rows total).
        // In one super-cycle:
        // - Serve 2 rows: 6 seconds (parallel)
        // - Move 1 row: 1 second
        // - Serve 2 rows: 6 seconds (parallel)
        // - Move 3 rows: 3 seconds
        // Total time per super-cycle: 6 + 1 + 6 + 3 = 16 seconds
        // Rows covered per super-cycle: 4 rows (e.g., 1-4, 5-8, 9-12, ...)

        // For row n:
        // Number of complete super-cycles before this row: (n-1) / 4
        // Time spent in complete super-cycles: ((n-1) / 4) * 16

        // Within the current super-cycle, determine the position:
        // rowInCycle: 0 -> row 1 of super-cycle (Att1)
        // rowInCycle: 1 -> row 2 of super-cycle (Att1)
        // rowInCycle: 2 -> row 3 of super-cycle (Att2)
        // rowInCycle: 3 -> row 4 of super-cycle (Att2)

        long fullCycles = (n - 1) / 4;
        long timeBeforeCycle = fullCycles * 16;

        long timeToStartServing;
        if (rowInCycle == 0) {
            // First row of the super-cycle, Att1
            timeToStartServing = 0;
        } else if (rowInCycle == 1) {
            // Second row of the super-cycle, Att1
            // After serving first row (6 sec) + move 1 row (1 sec)
            timeToStartServing = 6 + 1;
        } else if (rowInCycle == 2) {
            // Third row of the super-cycle, Att2
