        } else { // rowInCycle == 3
            // Fourth row of the super-cycle, Att2
            // Served in the second batch
            timeToStartServing = 6 + 1;
        }

        // Now add the time to reach the specific seat
        // Seats are served in order: f, e, d, c, b, a
        // f: 1st, e: 2nd, d: 3rd, c: 4th, b: 5th, a: 6th
        long seatTime;
        switch (seat) {
            case 'f': seatTime = 1; break;
            case 'e': seatTime = 2; break;
            case 'd': seatTime = 3; break;
            case 'c': seatTime = 4; break;
            case 'b': seatTime = 5; break;
            case 'a': seatTime = 6; break;
            default: seatTime = 0; break;
        }

        long totalTime = timeBeforeCycle + timeToStartServing + seatTime;

        System.out.println(totalTime);
    }
