        // After serving rows 1 and 3 (6 seconds each, but they work in parallel), they move 1 row forward (1 second)
        // Step 1: A1 at row 2, A2 at row 4. Start time: 6 + 1 = 7 seconds
        // After serving rows 2 and 4, they move 3 rows forward (3 seconds)
        // Step 2: A1 at row 5, A2 at row 7. Start time: 7 + 6 + 3 = 16 seconds
        // After serving rows 5 and 7, they move 1 row forward (1 second)
        // Step 3: A1 at row 6, A2 at row 8. Start time: 16 + 6 + 1 = 23 seconds
        // After serving rows 6 and 8, they move 3 rows forward (3 seconds)
        // Step 4: A1 at row 9, A2 at row 11. Start time: 23 + 6 + 3 = 32 seconds

        // Let's find the "step" number for row n
        // Attendant 1 rows: 1, 2, 5, 6, 9, 10, 13, 14, ...
        // Attendant 2 rows: 3, 4, 7, 8, 11, 12, 15, 16, ...

        // For attendant 1, the rows are: 1, 2, 5, 6, 9, 10, ...
        // Group k (0-indexed): rows 4k+1, 4k+2
        // For attendant 2, the rows are: 3, 4, 7, 8, 11, 12, ...
        // Group k (0-indexed): rows 4k+3, 4k+4

        long group;
        if (isAttendant1) {
            // n is of form 4k+1 or 4k+2
            // k = (n-1)/4 if n%4==1, or (n-2)/4 if n%4==2
            // Actually, for n=1: k=0, n=2: k=0, n=5: k=1, n=6: k=1
            group = (n - 1) / 4;
        } else {
            // n is of form 4k+3 or 4k+4
            // For n=3: k=0, n=4: k=0, n=7: k=1, n=8: k=1
            group = (n - 3) / 4;
        }

        // Now calculate the start time for this group
        // Each group takes 6 seconds to serve + move time
        // Move times alternate: 1, 3, 1, 3, ...
        // Group 0: start at 0
        // Group 1: start at 6 + 1 = 7
        // Group 2: start at 7 + 6 + 3 = 16
        // Group 3: start at 16 + 6 + 1 = 23
        // Group 4: start at 23 + 6 + 3 = 32

        // For group g, the start time is:
        // Sum of (6 + move_time) for all previous groups
        // move_time for transition from group i to group i+1:
        // From group 0 to 1: 1 second
        // From group 1 to 2: 3 seconds
        // From group 2 to 3: 1 second
        // From group 3 to 4: 3 seconds
        // So move_time for transition i (from group i to i+1) is: 1 if i is even, 3 if i is odd

        // Total time before group g starts:
        // = g * 6 + sum of move times for transitions 0 to g-1
        // Sum of move times for transitions 0 to g-1:
        // If g is even: there are g/2 transitions with move time 1 and g/2 transitions with move time 3
        //   Wait, let's check: transitions 0,1,2,...,g-1
        //   Transition 0: 1, Transition 1: 3, Transition 2: 1, Transition 3: 3, ...
        //   Number of 1's: ceil(g/2), Number of 3's: floor(g/2)
        //   Actually: for g transitions (0 to g-1):
        //   If g is even: g/2 ones and g/2 threes
        //   If g is odd: (g+1)/2 ones and (g-1)/2 threes

        long totalMoveTime;
        if (g % 2 == 0) {
            totalMoveTime = (g / 2) * 1 + (g / 2) * 3;
        } else {
            totalMoveTime = ((g + 1) / 2) * 1 + ((g - 1) / 2) * 3;
        }

        long startTime = g * 6 + totalMoveTime;

        // Now determine the offset within the row for the seat
        // Order of serving: f, e, d, c, b, a
        // f: 1st (1 second), e: 2nd, d: 3rd, c: 4th, b: 5th, a: 6th
        long seatOffset;
        switch (seat) {
            case 'f': seatOffset = 1; break;
            case 'e': seatOffset = 2; break;
            case 'd': seatOffset = 3; break;
            case 'c': seatOffset = 4; break;
            case 'b': seatOffset = 5; break;
            case 'a': seatOffset = 6; break;
            default: seatOffset = 0; break;
        }

        long result = startTime + seatOffset;
        System.out.println(result);
    }
